TLM.f("Tempora/Nat30",{"officium":"Die VI infra Octavam Nativitatis","rule":["ex Sancti/12-25m3;","Gloria","Credo","Prefatio=Nat"],"ruleInherited":["Gloria","Credo","Prefatio=Nat","celebranda aut missa prima aut missa secunda aut missa tertia","no Ultima Evangelium"],"fallback":"Sancti/12-25m3","sections":{"Introitus":[{"k":"ref","la":"Isa 9:6"},{"k":"text","la":"Puer natus est nobis, et fílius datus est nobis: cujus impérium super húmerum ejus: et vocábitur nomen ejus magni consílii Angelus."},{"k":"ref","la":"Ps 97:1"},{"k":"text","la":"Cantáte Dómino cánticum novum, quia mirabília fecit."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Puer natus est nobis, et fílius datus est nobis: cujus impérium super húmerum ejus: et vocábitur nomen ejus magni consílii Angelus."}],"Oratio":[{"k":"text","la":"Concéde, quǽsumus, omnípotens Deus: ut nos Unigéniti tui nova per carnem Natívitas líberet; quos sub peccáti jugo vetústa sérvitus tenet."},{"k":"macro","name":"Per eundem"}],"Lectio":[{"k":"text","la":"Lectio Epístolæ beati Pauli Apostoli ad Titum."},{"k":"ref","la":"Tit 3:4-7"},{"k":"text","la":"Caríssime: Appáruit benígnitas et humánitas Salvatóris nostri Dei: non ex opéribus justítiæ, quæ fécimus nos, sed secúndum suam misericórdiam salvos nos fecit per lavácrum regeneratiónis et renovatiónis Spíritus Sancti, quem effúdit in nos abúnde per Jesum Christum, Salvatorem nostrum: ut, justificáti grátia ipsíus, herédes simus secúndum spem vitæ ætérnæ: in Christo Jesu, Dómino nostro."}],"Graduale":[{"k":"ref","la":"Ps 97: 3, 4, 2"},{"k":"text","la":"Vidérunt omnes fines terræ salutare Dei nostri: jubiláte Deo, omnis terra."},{"k":"text","la":"Notum fecit Dominus salutare suum: ante conspéctum géntium revelávit justitiam suam. Allelúja, allelúja.","mark":"V"},{"k":"text","la":"Dies sanctificátus illúxit nobis: veníte, gentes, et adoráte Dóminum: quia hódie descéndit lux magna super terram. Allelúja.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam."},{"k":"ref","la":"Luc 2:15-20"},{"k":"text","la":"In illo témpore: Pastóres loquebántur ad ínvicem: Transeámus usque Béthlehem, et videámus hoc verbum, quod factum est, quod Dóminus osténdit nobis. Et venérunt festinántes: et invenérunt Maríam, et Joseph, et Infántem pósitum in præsépio. Vidéntes autem cognovérunt de verbo, quod dictum erat illis de Púero hoc. Et omnes, qui audiérunt, miráti sunt: et de his, quæ dicta erant a pastóribus ad ipsos. María autem conservábat ómnia verba hæc, cónferens in corde suo. Et revérsi sunt pastóres, glorificántes et laudántes Deum in ómnibus, quæ audíerant et víderant, sicut dictum est ad illos."}],"Offertorium":[{"k":"ref","la":"Ps 88:12; 88:15"},{"k":"text","la":"Tui sunt cœli et tua est terra: orbem terrárum et plenitúdinem ejus tu fundásti: justítia et judícium præparátio sedis tuæ."}],"Secreta":[{"k":"text","la":"Obláta, Dómine, múnera, nova Unigéniti tui Nativitáte sanctífica: nosque a peccatórum nostrórum máculis emúnda."},{"k":"macro","name":"Per eundem"}],"Communio":[{"k":"ref","la":"Ps 97:3"},{"k":"text","la":"Vidérunt omnes fines terræ salutáre Dei nostri."}],"Postcommunio":[{"k":"text","la":"Præsta, quǽsumus, omnípotens Deus: ut natus hódie Salvátor mundi, sicut divínæ nobis generatiónis est auctor; ita et immortalitátis sit ipse largítor:"},{"k":"macro","name":"Qui tecum"}]},"hr":{"2556a7cf67c03224":{"t":"Iz 9, 6, Ps 97, 1\n(Iz 9, 6) Dijete nam se rodilo i Sin nam je darovan. Znak mu je vlasti na ramenu, a ime mu je Anđeo velikoga savjeta. (Ps 97, 1) Pjevajte Gospodinu novu pjesmu, jer učini divna djela.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Iz 9, 6) Dijete nam se rodilo i Sin nam je darovan. Znak mu je vlasti na ramenu, a ime mu je Anđeo velikoga savjeta.","v":"∅ → filius; ∅ → filius","kn":"(Izai. 9, 6). Dijete nam se rodilo i sin ,nam je darovan; na svojim, ramenima nosi znak svoje vlasti, a njegovo je ime: Anđeo velikoga savjeta, (Ps. 97, 1). Pjevajte Gospodinu pjesmo' novu, jei^ učini divne .stvari! Slava Ocu . . . Dijete . . .","knRef":"Kniewald 1942, str. 66–67 (snimka 34) (OCR)"},"77f61766a40a00f2":{"t":"<i>Pomolimo se</i>.\nPodaj, molimo, svemogući Bože, da novo tjelesno rođenje tvoga jedinorođenog Sina oslobodi nas, koje staro sužanjstvo tišti jarmom grijeha.\n<i>Po istom Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Dopusti, molimo, svemogući Bože, da nas, koji stenjemo pod starim sužanj sivom i jarmom grijeha, oslobodi novo rođenje Tvogai Jedinca, što ga očekujemo, koji s Tobom živi i kraljuje . . .","knRef":"Kniewald 1942, str. 46–47 (snimka 24) (OCR)"},"e0f30f9a6fa2333c":{"t":"Tit 3, 4-7\nČitanje Poslanice bl. Pavla apostola Titu. Predragi: objavila se dobrota i čovjekoljublje Boga našega Spasitelja. On nas je spasio, ali ne po našim pravednim djelima nego po svojem milosrđu, po kupelji preporoda i obnove Duha Svetoga. Njega je na nas obilno izlio po našem Spasitelju Isusu Kristu, da opravdani njegovom milošću budemo po ufanju baštinici vječnog života u našem Gospodinu Isusu Kristu.","kn":"Čitanje poslanice bi, Pavla apostola Titu (3, 4-7). Predragi! Objavila se dobrota i čovjekoljublje Spasitelja našega Boga. On nas je spasio, ali ne po pravednim djelima., što smo ih mi učinili, nego po svomu milosrđu, po kupelji preporoda i obnove Duha Svetoga., koijega je obilno na nas izlio po Božić — ■ danja misa Isusu Kristu Spasitelju našemu, da opravdani njegovom milošću, po ufanju budemo baštinici vječnoga života u Isusu Kristu, Gospodinu našemu.","knRef":"Kniewald 1942, str. 58–59 (snimka 30) (OCR)"},"450255e358a9cd68":{"t":"Ps 97, 3-4 i 2\nSvi krajevi zemlje vidješe spasenje Boga našega. Kličite Bogu, sve zemlje. Gospodin je objavio svoje spasenje, otkrio svoju pravdu pred licem naroda.\n\n<i>Aleluja</i>, <i>aleluja</i>.\nZasjao nam je posvećeni dan. Dođite, narodi, i poklonite se Gospodinu, jer je danas velika svjetlost sašla na zemlju. <i>Aleluja</i>.","kn":"(Ps. 97, 3, 2). Svi krajevi zemlje vidješe spasenje Boga našega: zato neka kliče sva zemlja! Jer je očitovao Gospodin svoje spasenje: objavio je pravdu svim narodima.\n\nAleluja, aleluja. Zasjao nam je sveti dan: dođite, narodi, i poklonite se Gospodinu, jer je danas sašla velika svjetlost na zemlju, <i>aleluja</i>.","knRef":"Kniewald 1942, str. 62–63 (snimka 32) (OCR)"},"87d338e1955655ec":{"t":"Lk 2, 15-20\nSlijedi sveto Evanđelje po Luki. U ono vrijeme: pozovu pastiri jedan drugoga: »Pođimo u Betlehem da vidimo što se dogodilo, kako nam je objavio Gospodin!« Pođu žurno i nađu Mariju i Josipa i Dijete položeno u jasle. Kad su vidjeli, shvatili su što im je rečeno o tom Djetetu. Svi koji su čuli, divili su se onome što su im kazivali pastiri. Sve je te riječi Marija pamtila razmišljajući u svom srcu. A pastiri se vrate slaveći Boga za sve što su čuli i vidjeli, kako im je bilo rečeno.","kn":"t Slijedi sveto Evanđelje po Luki (2, 15-20). U ono vrijeme rekoše pastiri jedan drugome: Pođimo do Betlehema, da vidimo, što ee dogodilo, kako nam je objavio Gospodin. Pođu žurno i nađu Mariju i Josipa i dijete, gdje leži u jaslama. I kad oni odu, vidješe, i uvjeriše se o tom, što im je bilo rečeno o ovom djetetu. I svi, koji su čuli, divili su se onomu, što su im kazivali pastiri. A Marija je sve ovo pamtila razmišljajući u svom srcu. I pastiri se povratiše slaveći Boga za sve, što su čuli i vidjeli, kako im je bilo kazano.","knRef":"Kniewald 1942, str. 60–61 (snimka 31) (OCR)"},"1dcee0ba49089f56":{"t":"Ps 88, 12 i 15\nTvoja su nebesa, tvoja je zemlja, ti si stvorio zemaljski krug i sve što je na njemu. Pravda i pravo temelji su prijestolja tvoga.","kn":"(Ps. 88, 12-15). Tvoja .su nebesa i Tvoja je zemlja: Ti si osnovao zemaljski krug i sve što je na njemu; Pravednost je osnoiv Tvojemu prijestolju.","knRef":"Kniewald 1942, str. 68–69 (snimka 35) (OCR)"},"748a928b3dfd448c":{"t":"Prinesene darove, Gospodine, posveti novim rođenjem svoga Jedinorođenca, a nas od ljaga naših grijeha očisti.\n<i>Po istom Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Novim rođenjem Tvoga Jedinorođenoga posveti. Gospodine, darove, koje Ti prinosimo i očisti nas od ljaga naših grijeha. Po istom G. n. I. K _ Predslovlie božično.","knRef":"Kniewald 1942, str. 62–63 (snimka 32) (OCR)"},"46276ff06c5f858a":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine sveti Oče, svemogući i vječni Bože: jer je po tajni utjelovljene Riječi očima naše duše sinula nova svjetlost tvoga sjaja. Te dok tjelesnim očima spoznajemo Boga, on nas zanosi ljubavlju prema nevidljivim dobrima. I stoga s anđelima i arkanđelima, s prijestoljima i gospodstvima i sa svom nebeskom vojskom pjesmu tvoje slave pjevamo bez prestanka:","kn":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti, Oče svemogući, vječni Bože, jer je otajstvom utjelovljene Riječi očima naše duše zasjalo novo svijetlo Tvoje sjajnosti, te nas Bog, dok ga spoznajemo u vidljivom obličju, privlači da ljubimo i nevidljive stvari. I zato pjevamo pjesmu slave Tvoje s anđelima i arkanđelima, s prijestolima 1 s gospodstvima, sa svom silom nebeske vojske govoreći bez prestanka:","knRef":"Kniewald 1942, str. 20–21 (snimka 11) (OCR)"},"3497b8df953b1338":{"t":"Ps 97, 3\nSvi krajevi zemlje vidješe spasenje Boga našega.","kn":"(Ps. 97, 3). Vidješe svi krajevi zemlje spasenje Boga našega.","knRef":"Kniewald 1942, str. 62–63 (snimka 32) (OCR)"},"6e3f222713b3fa12":{"t":"<i>Pomolimo se</i>.\nPodaj, molimo, svemogući Bože, kao što je danas rođeni Spasitelj svijeta začetnik našega božanskoga rođenja, tako da bude i darovatelj besmrtnosti.\n<i>Koji s Tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Podaj, molimo, svemogući Bože, da nam danas rođeni Spasitelj svijeta daruje besmrtnost, kao što nam je darovao božanstveno rođenje (po milosti), koji s Tobom živi i kraljuje . . .","knRef":"Kniewald 1942, str. 62–63 (snimka 32) (OCR)"}}});
